import { DataSource } from 'typeorm';

export interface CreateQuizAnswersInput {
  [key: string]: unknown;
}

export async function createTestQuizAnswers(
  dataSource: DataSource,
  overrides: CreateQuizAnswersInput = {},
): Promise<Record<string, unknown>> {
  const meta = dataSource.entityMetadatas.find(
    (m) => m.name === 'QuizAnswers' || m.tableName === 'quiz_answers',
  );
  if (!meta) {
    throw new Error('createTestQuizAnswers: QuizAnswers entity not registered with the DataSource');
  }
  const repo = dataSource.getRepository(meta.target);
  const row: Record<string, unknown> = {
    isCorrect: false,
    answeredAt: new Date(),
    ...overrides,
  };
  const saved = await repo.save(row as never);
  return saved as unknown as Record<string, unknown>;
}
